  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settingsQuery = useSettings(sheet);
  const settings = settingsQuery.data;
  const shared = useShared(sheet);

  if (!user || !sheet) return null;

  // The figures are read as of the screen's as-of date: wait until every one is loaded for it.
  const ready = !!people.data && !!claims.data && !!rates.data && !!settingsQuery.data && today !== undefined;

  const download = () => {
    const late = lateOf(settings, today, people.data);
    const lines = [['name', 'grade', 'retired-from', 'due-total']];
    for (const p of people.data ?? []) {
      const due = personDue(live((claims.data ?? []).filter((c) => c.personId === p.id), [p]), rates.data, p.grades, today, floorOf(settings), late, settings?.cap, shared(p));
      lines.push([p.name, gradeOn(p.grades, today), p.retiredFrom ?? '', due]);
    }
    const csv = lines.map((l) => l.map(cell).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `people-${sheet}.csv`;
    document.body.appendChild(a);
    a.click();
  const fig = useFigure();
  const [sheet] = useCurrentSheet();
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const periods = usePeriods(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  const floor = floorOf(settings);
  const late = lateOf(settings, today, people.data);
  const voidReasons = useVoidReasons(sheet).data ?? [];
  const shared = useShared(sheet);

  const active = (people.data ?? []).filter((p) => !p.retired);
  const onGrade = (grade: string) => active.filter((p) => gradeOn(p.grades, today) === grade);
  const dueOf = (p: (typeof active)[number]) =>
    personDue(live((claims.data ?? []).filter((c) => c.personId === p.id), [p]), rates.data, p.grades, today, floor, late, settings?.cap, shared(p));

  const periodTotal = (p: NonNullable<typeof periods.data>[number]) =>
    periodDue(p, claims.data, people.data, rates.data, floor, late);
  const byStart = [...(periods.data ?? [])].sort((a, b) => a.from.localeCompare(b.from));
